import{Z as e,et as t,mt as n,s as r,tt as i}from"./chunks/framework.C92HYyu1.js";import"./chunks/assets.tD9y118P.js";var a=JSON.parse(`{"title":"データセット","description":"AIベースのテスト自動化でQA時間を80%削減します。コードなしのテスト作成、自然言語によるシナリオ作成、多様なプラットフォームのサポートにより、QAの新しい基準を提示します。","frontmatter":{"title":"データセット","description":"AIベースのテスト自動化でQA時間を80%削減します。コードなしのテスト作成、自然言語によるシナリオ作成、多様なプラットフォームのサポートにより、QAの新しい基準を提示します。","head":[["meta",{"name":"keywords","content":"テスト自動化, テスティング生成型AI, Playwright, Selenium, リアルタイム品質フィードバック, 無停止テスト, AIベーステスト自動化, 継続的テスト(Continuous Testing), QAOps, TestOps, コードレス(Codeless), ローコード(Low-Code), 自己修復テスト(Self-healing), AIテスト自動化, コードレス自動化, QA自動化, ソフトウェアテスト, テストシナリオ生成, コードレステスト, 自然言語テスト, テスト自動化ツール, テスト自動化プラットフォーム, テスト効率化, Playwright, Selenium, QAOps, TestOps, シフトレフト(Shift-Left)テスト, シフトライト(Shift-Right)テスト"}],["meta",{"property":"og:title","content":"AIテスト自動化 | SyncETA"}],["meta",{"property":"og:description","content":"AIベースのテスト自動化でQA時間を80%削減します。コードなしのテスト作成、自然言語によるシナリオ作成、多様なプラットフォームのサポートにより、QAの新しい基準を提示します。"}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/synceta/"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/ja/synceta/dataset.html"}]],"sort":700},"headers":[],"relativePath":"ja/synceta/dataset.md","filePath":"ja/synceta/dataset.md","lastUpdated":1787437905000}`),o={name:`ja/synceta/dataset.md`};function s(r,a,o,s,c,l){return n(),t(`div`,null,[...a[0]||=[i(`<h1 id="データセット" tabindex="-1">データセット <a class="header-anchor" href="#データセット" aria-label="Permalink to “データセット”">​</a></h1><h2 id="データセットとは" tabindex="-1">データセットとは？ <a class="header-anchor" href="#データセットとは" aria-label="Permalink to “データセットとは？”">​</a></h2><p>データセットは、Key-Value構造で事前に生成されたモックアップデータを、シナリオに設定された変数と自動的にマッピングする役割を果たします。 事前に定義した変数に基づいてモックアップデータを生成することができ、AIを活用して変数に適したデータを自動的に生成してくれます。</p><h2 id="データセットの作成" tabindex="-1">データセットの作成 <a class="header-anchor" href="#データセットの作成" aria-label="Permalink to “データセットの作成”">​</a></h2><p>データセットはExcelシートに似た構造で設計されており、ユーザーに馴染みがあり、簡単に作成および管理できます。</p><p>変数と行を自由に追加および削除でき、シナリオで事前に設定した変数値を呼び出す機能を提供します。 Excelファイルで事前に生成されたデータをインポートすることができ、変数設定後にAIを活用してモックアップデータを自動的に生成することができます。</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><ul><li>シートを右クリックしてください</li></ul></div><p><img src="/docs/assets/dataset.5iXXPzxJ.png" alt="image" loading="lazy"></p><h2 id="excelで作成する" tabindex="-1">Excelで作成する <a class="header-anchor" href="#excelで作成する" aria-label="Permalink to “Excelで作成する”">​</a></h2><h4 id="excel-form-ダウンロード" tabindex="-1">Excel form <a href="./image/dataset/dataset_form.xlsx">ダウンロード</a> <a class="header-anchor" href="#excel-form-ダウンロード" aria-label="Permalink to “Excel form ダウンロード”">​</a></h4><p><img src="/docs/assets/exel.CL7tt1gh.png" alt="image" loading="lazy"></p><h2 id="aiを活用した自動生成" tabindex="-1">AIを活用した自動生成 <a class="header-anchor" href="#aiを活用した自動生成" aria-label="Permalink to “AIを活用した自動生成”">​</a></h2><p>変数設定後、「AIでデータを自動入力」をクリックすると、AIが変数に合ったモックアップデータを自動的に生成してくれます。</p><ul><li>ローディング <img src="/docs/assets/dataset_loading.DBtE2YtU.png" alt="image" loading="lazy"></li><li>データ生成後の画面 <img src="/docs/assets/dataset_ai.CDuljMGU.png" alt="image" loading="lazy"></li></ul><h2 id="データセットの適用" tabindex="-1">データセットの適用 <a class="header-anchor" href="#データセットの適用" aria-label="Permalink to “データセットの適用”">​</a></h2>`,15),e(`iframe`,{width:`100%`,height:`400`,src:`https://www.youtube.com/embed/d2RU8aabXIQ`,frameborder:`0`,allowfullscreen:``,allow:`autoplay; encrypted-media`},null,-1)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};